#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: deploy de Plektia a Cloudflare Workers y proyecto de Supabase en la nube.
# Uso (desde la raíz del repo, en Git Bash): bash scripts/wizard-deploy.sh
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=6
# El repo sale del clon actual (el fork de quien corre el wizard, no el original).
REPO=$(gh repo view --json nameWithOwner --jq .nameWithOwner 2>/dev/null || true)
GH_ENV="production"

# Secretos y variables del entorno `production` de GitHub: solo los ve el job de
# deploy (.github/workflows/deploy.yml), no la CI de los PRs.
set_env_secret() {
  local name="$1" value="$2"
  if printf '%s' "$value" | gh secret set "$name" --env "$GH_ENV" --repo "$REPO" >/dev/null 2>&1; then
    WRITTEN_SECRET+=("$name")
    printf '  %s✓ set%s secreto %s (entorno %s)\n' "$GREEN" "$RESET" "$name" "$GH_ENV"
  else
    SKIPPED+=("secreto $name: gh secret set $name --env $GH_ENV --repo $REPO")
    warn "no pude guardar el secreto $name; queda para hacerlo a mano"
  fi
}
set_env_var() {
  local name="$1" value="$2"
  if gh variable set "$name" --env "$GH_ENV" --repo "$REPO" --body "$value" >/dev/null 2>&1; then
    printf '  %s✓ set%s variable %s (entorno %s)\n' "$GREEN" "$RESET" "$name" "$GH_ENV"
  else
    SKIPPED+=("variable $name: gh variable set $name --env $GH_ENV --repo $REPO --body <valor>")
    warn "no pude guardar la variable $name; queda para hacerla a mano"
  fi
}

# En Git Bash (Windows), explorer.exe recibe las URLs con `=/...` convertidas en
# rutas de archivo y abre el Explorador. Ahí se abre el navegador por defecto
# con el manejador de URLs de Windows, sin conversión de rutas.
if command -v rundll32.exe >/dev/null 2>&1; then
  open_url() {
    printf '  %s↗ abriendo%s %s
' "$GREEN" "$RESET" "$1"
    MSYS_NO_PATHCONV=1 rundll32.exe url.dll,FileProtocolHandler "$1" >/dev/null 2>&1 ||
      warn "no pude abrir el navegador; abrí la URL a mano: $1"
  }
fi

# Los valores no se guardan en disco: el token va directo a GitHub.
ENV_FILE="/dev/null"

banner "Plektia · deploy a Cloudflare + Supabase en la nube"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Cloudflare: iniciar sesión en Wrangler"
note "Para pegar en esta terminal: clic derecho o Shift+Insert. Ctrl+C corta el wizard."
WHOAMI=$(pnpm exec wrangler whoami 2>&1 || true)
if grep -q "You are logged in" <<<"$WHOAMI"; then
  printf '  %s✓ ya tenés sesión iniciada en Wrangler%s
' "$GREEN" "$RESET"
  pause "Enter para seguir"
else
  say "Wrangler va a abrir el navegador para que autorices el acceso a tu cuenta."
  say "Este login queda solo en esta PC; la CI usa otro token, más acotado."
  step "En la página de Cloudflare, revisá los permisos y tocá 'Allow'."
  pause "Enter para abrir el login..."
  pnpm exec wrangler login
  WHOAMI=$(pnpm exec wrangler whoami 2>&1 || true)
fi

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Cloudflare: primer deploy (crea el Worker)"
say "Se compila el proyecto y se publica el Worker 'plektia' en workers.dev."
say "Si tu cuenta todavía no tiene subdominio workers.dev, Wrangler te pide elegir uno."
warn "Esto publica la app en una URL pública."
if confirm "¿Publico ahora? (respondé n si ya lo publicaste en una corrida anterior)"; then
  pnpm build
  pnpm deploy:worker
fi
step "Escribí la URL del Worker (https://plektia.<tu-subdominio>.workers.dev)."
ask PRODUCTION_URL "URL:"
PRODUCTION_URL="${PRODUCTION_URL%/}"

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Cloudflare: Account ID"
CLOUDFLARE_ACCOUNT_ID=$(grep -oE '[0-9a-f]{32}' <<<"$WHOAMI" | head -n1 || true)
if [[ -n "$CLOUDFLARE_ACCOUNT_ID" ]] && confirm "Tu Account ID es $CLOUDFLARE_ACCOUNT_ID. ¿Es correcto?"; then
  printf '  %s✓ Account ID tomado de Wrangler%s
' "$GREEN" "$RESET"
else
  pnpm exec wrangler whoami || true
  step "Buscá la columna 'Account ID' (32 caracteres hexadecimales)."
  ask CLOUDFLARE_ACCOUNT_ID "Pegá el Account ID:"
fi

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Cloudflare: token de deploy para la CI"
say "Creamos un token de cuenta que solo puede desplegar el Worker 'plektia'."
open_url "https://dash.cloudflare.com/?to=/:account/api-tokens"
step "Tocá 'Create Token' → 'Create Custom Token'."
step "Nombre: plektia-deploy-ci"
step "Permisos: Workers → rol 'Editor', con alcance solo al Worker 'plektia'."
note "Si tu panel no ofrece alcance por Worker, elegí Workers → Editor para la cuenta."
step "Sin filtro de IP (los runners de GitHub cambian de IP). Vencimiento: 1 año."
step "Continue to summary → Create Token → copiá el token (se muestra una sola vez)."
note "Al pegar no se ve nada (es a propósito): clic derecho o Shift+Insert y Enter."
ask_secret CLOUDFLARE_API_TOKEN "Pegá el token:"
say "Verificando el token con la API de Cloudflare..."
if curl -fsS "https://api.cloudflare.com/client/v4/accounts/${CLOUDFLARE_ACCOUNT_ID}/tokens/verify" \
  -H "Authorization: Bearer ${CLOUDFLARE_API_TOKEN}" | grep -q '"status":"active"'; then
  printf '  %s✓ token activo%s\n' "$GREEN" "$RESET"
else
  warn "Cloudflare no confirmó el token. Revisá que lo copiaste entero y que es de esta cuenta."
  pause "Enter para seguir igual (o Ctrl-C para cortar y re-ejecutar)"
fi

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "GitHub: entorno 'production' y sus secretos"
if [[ -z "$REPO" ]]; then
  warn "No pude detectar el repo de GitHub de este clon (¿gh sin login?)."
  ask REPO "Escribí el repo (usuario/nombre):"
fi
say "Creo el entorno 'production' en $REPO, limitado a ramas protegidas (main),"
say "y guardo ahí el token, el Account ID y la URL pública."
if confirm "¿Es tu repo $REPO y configuro GitHub ahora?"; then
  if gh api -X PUT "repos/$REPO/environments/$GH_ENV" --input - >/dev/null <<'JSON'
{"deployment_branch_policy": {"protected_branches": true, "custom_branch_policies": false}}
JSON
  then
    printf '  %s✓ entorno%s %s listo\n' "$GREEN" "$RESET" "$GH_ENV"
    set_env_secret CLOUDFLARE_API_TOKEN "$CLOUDFLARE_API_TOKEN"
    set_env_secret CLOUDFLARE_ACCOUNT_ID "$CLOUDFLARE_ACCOUNT_ID"
    set_env_var PRODUCTION_URL "$PRODUCTION_URL"
  else
    warn "No pude crear el entorno en $REPO: ¿tenés permisos de administrador ahí?"
    SKIPPED+=("entorno $GH_ENV y sus secretos en $REPO")
  fi
else
  SKIPPED+=("entorno $GH_ENV y sus secretos en GitHub")
fi
unset CLOUDFLARE_API_TOKEN

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Supabase: proyecto en la nube"
say "Se crea vacío; las migraciones y las claves se conectan en las tareas siguientes."
open_url "https://supabase.com/dashboard/new"
step "Organización: la tuya. Nombre: plektia."
step "Database password: tocá 'Generate a password' y guardala en tu gestor de contraseñas."
step "Región: South America (São Paulo), la más cercana."
step "Dejá el resto por defecto y tocá 'Create new project'."
step "Cuando termine, copiá el Project ID / Reference ID (Project Settings → General)."
ask SUPABASE_PROJECT_REF "Pegá el Project ID (20 letras):"
set_env_var SUPABASE_PROJECT_REF "$SUPABASE_PROJECT_REF"

finish
say "Probá la URL: $PRODUCTION_URL"
